String translateNotifDynamic(String lang, String text) {
  final i = _langOrder.indexOf(lang);
  if (i < 0) return text;
  final hit = notifPhrases[text];
  if (hit != null) return hit[i];
  for (final e in {
    r'^(\w+) has entered$': _enteredTpl,
    r'^Return for (\w+)\.$': _returnTpl,
    r'^(\w+) time is still open\.$': _openTpl,
  }.entries) {
    final m = RegExp(e.key).firstMatch(text);
    if (m != null) {
      final name = _prayerNames[m.group(1)!];
      return e.value[i].replaceAll('{p}', name == null ? m.group(1)! : name[i]);
    }
  }
  return text;
}

